diff --git a/src/ui/glyph_cache.h b/src/ui/glyph_cache.h
index 6cbc1ca..23d3c5f 100644
--- a/src/ui/glyph_cache.h
+++ b/src/ui/glyph_cache.h
@@ -5,6 +5,7 @@
 #include <stdint.h>

 // Glyphs rasterise on first use at the exact pixel size into RGBA8 atlas pages: white, with coverage in alpha.
+// Colour emoji share the pages, resampled to a Font Size square.
 // When every page is full, the least recently used one is cleared; one used this frame is never cleared.
 #define VD_GLYPH_ATLAS_PAGE_SIZE 1024
 #define VD_GLYPH_ATLAS_PAGE_BYTES (VD_GLYPH_ATLAS_PAGE_SIZE * VD_GLYPH_ATLAS_PAGE_SIZE * 4)
@@ -12,6 +13,9 @@

 #define VD_UTF8_REPLACEMENT 0xfffd

+// The longest Twemoji sequence, a couple kissing with skin tones, has 9 codepoints once U+FE0F is left out.
+#define VD_EMOJI_SEQUENCE_MAX 10
+
 typedef struct VdGlyphFont VdGlyphFont;

 typedef struct {
@@ -28,8 +32,18 @@ typedef struct {
     // From the pen position on the baseline to the bitmap's top-left corner.
     int offset_x, offset_y;
     float advance;
+    // Drawn untinted: a colour emoji.
+    bool color;
 } VdGlyph;

+typedef struct {
+    uint32_t codepoints[VD_EMOJI_SEQUENCE_MAX];
+    int length;
+} VdEmojiSequence;
+
+// The RGBA8 image for a codepoint sequence, U+FE0F left out, in memory from malloc; NULL when there is none.
+typedef unsigned char *(*VdEmojiLoader)(const VdEmojiSequence *sequence, int *width, int *height);
+
 typedef struct {
     int pages;
     int glyphs;
@@ -45,6 +59,10 @@ VdGlyphFontMetrics glyph_font_metrics(const VdGlyphFont *font, int size);
 // Codepoints a font lacks come from the fallback; ones neither has draw the requested font's missing-glyph box.
 void glyph_cache_set_fallback(const VdGlyphFont *font);
 VdGlyph glyph_cache_get(const VdGlyphFont *font, int size, uint32_t codepoint);
+void glyph_cache_set_emoji_loader(VdEmojiLoader loader);
+// The emoji for the longest prefix of sequence that has an image, as a Font Size square on the font's line; false
+// when no prefix has one. A ZWJ sequence without its own image so draws as its first emoji.
+bool glyph_cache_get_emoji(const VdGlyphFont *font, int size, const VdEmojiSequence *sequence, VdGlyph *glyph);
 void glyph_cache_begin_frame(void);
 // Drops every glyph and page.
 void glyph_cache_reset(void);
@@ -55,5 +73,9 @@ VdGlyphCacheStats glyph_cache_stats(void);
 // Decodes the codepoint at text, which must not be at its terminator, and sets length to the bytes it used.
 // Malformed UTF-8 decodes one byte at a time as VD_UTF8_REPLACEMENT.
 uint32_t vd_utf8_next(const char *text, int *length);
+// The bytes of the emoji cluster at text, with its codepoints in sequence, or 0 when text does not start one. A
+// cluster starts at a codepoint from U+1F000 up or one followed by U+FE0F or a keycap mark, and takes skin tones,
+// tags, a second regional indicator and ZWJ-joined codepoints.
+int vd_emoji_cluster(const char *text, VdEmojiSequence *sequence);

 #endif /* GLYPH_CACHE_H */

diff --git a/src/ui/glyph_cache.c b/src/ui/glyph_cache.c
index 75797d7..e6c7653 100644
--- a/src/ui/glyph_cache.c
+++ b/src/ui/glyph_cache.c
@@ -1,5 +1,6 @@
 #include "glyph_cache.h"

+#include <math.h>
 #include <stdlib.h>
 #include <string.h>
 #include "core/util.h"
@@ -12,6 +13,10 @@

 #define GLYPH_PADDING 1

+#define ZWJ 0x200d
+#define VS16 0xfe0f
+#define KEYCAP 0x20e3
+
 struct VdGlyphFont {
     char *data;
     stbtt_fontinfo info;
@@ -28,6 +33,19 @@ typedef struct {
     VdGlyph value;
 } GlyphEntry;

+// Emoji sit at the font's ascent, so the key holds the font.
+typedef struct {
+    const VdGlyphFont *font;
+    int size;
+    VdEmojiSequence sequence;
+} EmojiKey;
+
+// A glyph that is not color marks a sequence with no image.
+typedef struct {
+    EmojiKey key;
+    VdGlyph value;
+} EmojiEntry;
+
 // Shelf packing: glyphs fill a row left to right, and a row is as tall as its tallest glyph.
 typedef struct {
     unsigned char *pixels;
@@ -37,6 +55,8 @@ typedef struct {
 } AtlasPage;

 static GlyphEntry *g_glyphs = NULL;
+static EmojiEntry *g_emoji = NULL;
+static VdEmojiLoader g_emoji_loader = NULL;
 static AtlasPage g_pages[VD_GLYPH_ATLAS_PAGE_MAX];
 static int g_page_count = 0;
 static int g_current_page = -1;
@@ -127,6 +147,11 @@ static void clear_page(int index)
         GlyphKey key = g_glyphs[i].key;
         hmdel(g_glyphs, key);
     }
+    for (ptrdiff_t i = hmlen(g_emoji) - 1; i >= 0; i--) {
+        if (g_emoji[i].value.page != index) continue;
+        EmojiKey key = g_emoji[i].key;
+        hmdel(g_emoji, key);
+    }
 }

 // The page that now holds a width x height rect at (x, y), or -1 when no page can take it this frame.
@@ -187,7 +212,7 @@ static bool rasterise(const VdGlyphFont *font, int glyph_index, int size, VdGlyp

     g_pages[page].dirty = true;
     g_pages[page].last_used = g_frame;
-    *out = (VdGlyph){page, x, y, width, height, x0, y0, out->advance};
+    *out = (VdGlyph){page, x, y, width, height, x0, y0, out->advance, false};
     return true;
 }

@@ -224,6 +249,101 @@ VdGlyph glyph_cache_get(const VdGlyphFont *font, int size, uint32_t codepoint)
     return glyph;
 }

+void glyph_cache_set_emoji_loader(VdEmojiLoader loader)
+{
+    g_emoji_loader = loader;
+}
+
+// Area-averages the image into a size x size square, weighting colour by alpha so edges do not darken.
+static bool rasterise_emoji(const VdGlyphFont *font, int size, const unsigned char *image, int image_width,
+                            int image_height, VdGlyph *out)
+{
+    float ascent = glyph_font_metrics(font, size).ascent;
+    *out = (VdGlyph){.page = -1, .offset_y = -(int)roundf(ascent), .advance = (float)size, .color = true};
+    int x = 0, y = 0;
+    int page = atlas_allocate(size, size, &x, &y);
+    if (page < 0) return false;
+
+    unsigned char *pixels = g_pages[page].pixels;
+    for (int row = 0; row < size; row++) {
+        int y0 = row * image_height / size;
+        int y1 = (row + 1) * image_height / size;
+        if (y1 <= y0) y1 = y0 + 1;
+        for (int col = 0; col < size; col++) {
+            int x0 = col * image_width / size;
+            int x1 = (col + 1) * image_width / size;
+            if (x1 <= x0) x1 = x0 + 1;
+            unsigned long r = 0, g = 0, b = 0, a = 0;
+            for (int sy = y0; sy < y1; sy++) {
+                for (int sx = x0; sx < x1; sx++) {
+                    const unsigned char *source = image + ((size_t)sy * (size_t)image_width + (size_t)sx) * 4;
+                    r += (unsigned long)source[0] * source[3];
+                    g += (unsigned long)source[1] * source[3];
+                    b += (unsigned long)source[2] * source[3];
+                    a += source[3];
+                }
+            }
+            unsigned char *pixel = pixels + ((size_t)(y + row) * VD_GLYPH_ATLAS_PAGE_SIZE + (size_t)(x + col)) * 4;
+            unsigned long count = (unsigned long)(x1 - x0) * (unsigned long)(y1 - y0);
+            pixel[0] = a ? (unsigned char)(r / a) : 0;
+            pixel[1] = a ? (unsigned char)(g / a) : 0;
+            pixel[2] = a ? (unsigned char)(b / a) : 0;
+            pixel[3] = (unsigned char)(a / count);
+        }
+    }
+
+    g_pages[page].dirty = true;
+    g_pages[page].last_used = g_frame;
+    out->page = page;
+    out->x = x;
+    out->y = y;
+    out->width = out->height = size;
+    return true;
+}
+
+bool glyph_cache_get_emoji(const VdGlyphFont *font, int size, const VdEmojiSequence *sequence, VdGlyph *glyph)
+{
+    for (int length = sequence->length; length > 0; length--) {
+        if (sequence->codepoints[length - 1] == ZWJ) continue;
+        EmojiKey key;
+        memset(&key, 0, sizeof(key));
+        key.font = font;
+        key.size = size;
+        key.sequence.length = length;
+        memcpy(key.sequence.codepoints, sequence->codepoints, (size_t)length * sizeof(uint32_t));
+
+        ptrdiff_t found = hmgeti(g_emoji, key);
+        if (found >= 0) {
+            if (!g_emoji[found].value.color) continue;
+            *glyph = g_emoji[found].value;
+            if (glyph->page >= 0) g_pages[glyph->page].last_used = g_frame;
+            return true;
+        }
+
+        int width = 0, height = 0;
+        unsigned char *image = g_emoji_loader ? g_emoji_loader(&key.sequence, &width, &height) : NULL;
+        if (!image || width <= 0 || height <= 0) {
+            free(image);
+            hmput(g_emoji, key, ((VdGlyph){.page = -1}));
+            continue;
+        }
+        bool placed = true;
+        if (size > VD_GLYPH_ATLAS_PAGE_SIZE) {
+            // It keeps its advance and draws nothing, rather than loading again every frame.
+            *glyph = (VdGlyph){.page = -1, .advance = (float)size, .color = true};
+        } else {
+            placed = rasterise_emoji(font, size, image, width, height, glyph);
+        }
+        free(image);
+        if (placed) {
+            hmput(g_emoji, key, *glyph);
+            g_rasterised++;
+        }
+        return true;
+    }
+    return false;
+}
+
 void glyph_cache_begin_frame(void)
 {
     g_frame++;
@@ -238,6 +358,7 @@ void glyph_cache_reset(void)
     g_page_count = 0;
     g_current_page = -1;
     hmfree(g_glyphs);
+    hmfree(g_emoji);
     g_rasterised = 0;
 }

@@ -288,3 +409,54 @@ uint32_t vd_utf8_next(const char *text, int *length)
     *length = count;
     return codepoint;
 }
+
+static bool is_regional_indicator(uint32_t codepoint)
+{
+    return codepoint >= 0x1f1e6 && codepoint <= 0x1f1ff;
+}
+
+static bool joins_emoji(uint32_t codepoint)
+{
+    bool skin_tone = codepoint >= 0x1f3fb && codepoint <= 0x1f3ff;
+    bool tag = codepoint >= 0xe0020 && codepoint <= 0xe007f;
+    return skin_tone || tag || codepoint == KEYCAP;
+}
+
+static void append(VdEmojiSequence *sequence, uint32_t codepoint)
+{
+    sequence->codepoints[sequence->length++] = codepoint;
+}
+
+int vd_emoji_cluster(const char *text, VdEmojiSequence *sequence)
+{
+    int bytes = 0;
+    uint32_t first = vd_utf8_next(text, &bytes);
+    int next_length = 0;
+    uint32_t next = text[bytes] != '\0' ? vd_utf8_next(text + bytes, &next_length) : 0;
+    if (first < 0x1f000 && next != VS16 && next != KEYCAP) return 0;
+
+    memset(sequence, 0, sizeof(*sequence));
+    append(sequence, first);
+    while (text[bytes] != '\0') {
+        int length = 0;
+        uint32_t codepoint = vd_utf8_next(text + bytes, &length);
+        if (codepoint == VS16) {
+            bytes += length;
+            continue;
+        }
+        if (codepoint == ZWJ) {
+            if (text[bytes + length] == '\0' || sequence->length + 2 > VD_EMOJI_SEQUENCE_MAX) break;
+            int joined_length = 0;
+            uint32_t joined = vd_utf8_next(text + bytes + length, &joined_length);
+            append(sequence, ZWJ);
+            append(sequence, joined);
+            bytes += length + joined_length;
+            continue;
+        }
+        bool flag = sequence->length == 1 && is_regional_indicator(first) && is_regional_indicator(codepoint);
+        if ((!flag && !joins_emoji(codepoint)) || sequence->length == VD_EMOJI_SEQUENCE_MAX) break;
+        append(sequence, codepoint);
+        bytes += length;
+    }
+    return bytes;
+}

diff --git a/tests/glyph_cache_harness.c b/tests/glyph_cache_harness.c
index 6dfce59..0508940 100644
--- a/tests/glyph_cache_harness.c
+++ b/tests/glyph_cache_harness.c
@@ -4,6 +4,7 @@

 #include <math.h>
 #include <stdio.h>
+#include <stdlib.h>
 #include <string.h>

 // DejaVuSans-ascii.ttf is assets/fonts/DejaVuSans.ttf subset to U+0020-007E, under the same licence.
@@ -143,6 +144,130 @@ static void test_hungarian(const VdGlyphFont *full)
     }
 }

+static void expect_cluster(const char *text, int bytes, const uint32_t *codepoints, int count, const char *message)
+{
+    VdEmojiSequence sequence = {0};
+    int got = vd_emoji_cluster(text, &sequence);
+    bool same = got == bytes && (bytes == 0 || sequence.length == count);
+    for (int i = 0; same && bytes > 0 && i < count; i++) {
+        same = sequence.codepoints[i] == codepoints[i];
+    }
+    if (same) return;
+    fprintf(stderr, "glyph_cache_harness: cluster of %d bytes and %d codepoints, want %d and %d\n", got,
+            sequence.length, bytes, count);
+    expect(false, message);
+}
+
+static void test_emoji_clusters(void)
+{
+    expect_cluster("A", 0, NULL, 0, "a letter is not an emoji");
+    expect_cluster("\xe2\x9d\xa4", 0, NULL, 0, "a text-style symbol without U+FE0F is not an emoji");
+    expect_cluster("1", 0, NULL, 0, "a digit is not an emoji");
+    expect_cluster("\xf0\x9f\x8e\xae!", 4, (const uint32_t[]){0x1f3ae}, 1, "a single emoji is one codepoint");
+    expect_cluster("\xe2\x9d\xa4\xef\xb8\x8f", 6, (const uint32_t[]){0x2764}, 1,
+                   "U+FE0F makes a symbol an emoji and is left out of the sequence");
+    expect_cluster("\xf0\x9f\x91\x8d\xf0\x9f\x8f\xbd", 8, (const uint32_t[]){0x1f44d, 0x1f3fd}, 2,
+                   "a skin tone joins its emoji");
+    expect_cluster("\xf0\x9f\x87\xad\xf0\x9f\x87\xba\xf0\x9f\x87\xad\xf0\x9f\x87\xba", 8,
+                   (const uint32_t[]){0x1f1ed, 0x1f1fa}, 2, "a flag is two regional indicators");
+    expect_cluster("1\xef\xb8\x8f\xe2\x83\xa3", 7, (const uint32_t[]){0x31, 0x20e3}, 2, "a keycap keeps its mark");
+    expect_cluster("\xf0\x9f\x91\xa8\xe2\x80\x8d\xf0\x9f\x91\xa9\xe2\x80\x8d\xf0\x9f\x91\xa7 x", 18,
+                   (const uint32_t[]){0x1f468, 0x200d, 0x1f469, 0x200d, 0x1f467}, 5, "a ZWJ sequence is one cluster");
+    expect_cluster("\xf0\x9f\x91\xa8\xe2\x80\x8d", 4, (const uint32_t[]){0x1f468}, 1,
+                   "a trailing ZWJ is not part of the cluster");
+}
+
+// Pretends assets/emoji holds 1f3ae, 2764 and 1f468: 8x8 images, opaque red inside a transparent border.
+static int emoji_loads = 0;
+static int emoji_last_length = 0;
+
+static unsigned char *fake_emoji_loader(const VdEmojiSequence *sequence, int *width, int *height)
+{
+    emoji_loads++;
+    emoji_last_length = sequence->length;
+    uint32_t first = sequence->codepoints[0];
+    if (sequence->length != 1 || (first != 0x1f3ae && first != 0x2764 && first != 0x1f468)) return NULL;
+    *width = *height = 8;
+    unsigned char *pixels = calloc(8 * 8, 4);
+    for (int row = 1; pixels && row < 7; row++) {
+        for (int col = 1; col < 7; col++) {
+            unsigned char *pixel = pixels + (row * 8 + col) * 4;
+            pixel[0] = 255;
+            pixel[3] = 255;
+        }
+    }
+    return pixels;
+}
+
+static VdEmojiSequence cluster_of(const char *text)
+{
+    VdEmojiSequence sequence = {0};
+    vd_emoji_cluster(text, &sequence);
+    return sequence;
+}
+
+static void test_emoji(const VdGlyphFont *full)
+{
+    glyph_cache_reset();
+    glyph_cache_set_emoji_loader(fake_emoji_loader);
+    const int size = 24;
+
+    VdEmojiSequence controller = cluster_of("\xf0\x9f\x8e\xae");
+    VdGlyph emoji = {0};
+    expect(glyph_cache_get_emoji(full, size, &controller, &emoji), "an emoji with an image resolves");
+    expect(emoji.color && emoji.page == 0, "an emoji is a colour glyph in an atlas page");
+    expect(emoji.width == size && emoji.height == size && emoji.advance == (float)size,
+           "an emoji is a Font Size square");
+    expect(emoji.offset_y == -(int)roundf(glyph_font_metrics(full, size).ascent), "an emoji sits at the ascent");
+
+    const unsigned char *pixels = glyph_cache_take_dirty_page(0);
+    expect(pixels != NULL, "an emoji marks its page dirty");
+    if (pixels) {
+        const unsigned char *center =
+            pixels + ((size_t)(emoji.y + size / 2) * VD_GLYPH_ATLAS_PAGE_SIZE + (size_t)(emoji.x + size / 2)) * 4;
+        const unsigned char *corner = pixels + ((size_t)emoji.y * VD_GLYPH_ATLAS_PAGE_SIZE + (size_t)emoji.x) * 4;
+        expect(center[0] == 255 && center[1] == 0 && center[2] == 0 && center[3] == 255,
+               "an emoji keeps its colour in the RGBA page");
+        expect(corner[3] == 0, "an emoji keeps its transparent border");
+    }
+
+    int loads = emoji_loads;
+    VdGlyph again = {0};
+    glyph_cache_get_emoji(full, size, &controller, &again);
+    expect(same_glyph(emoji, again) && emoji_loads == loads, "a cached emoji does not load again");
+    VdGlyph large = {0};
+    glyph_cache_get_emoji(full, size * 2, &controller, &large);
+    expect(large.width == size * 2 && !same_glyph(emoji, large), "another size is another emoji");
+
+    VdEmojiSequence heart = cluster_of("\xe2\x9d\xa4\xef\xb8\x8f");
+    VdGlyph red_heart = {0};
+    expect(glyph_cache_get_emoji(full, size, &heart, &red_heart) && red_heart.color,
+           "a symbol with U+FE0F resolves to its emoji image");
+
+    VdEmojiSequence family = cluster_of("\xf0\x9f\x91\xa8\xe2\x80\x8d\xf0\x9f\x91\xa9\xe2\x80\x8d\xf0\x9f\x91\xa7");
+    VdEmojiSequence man = cluster_of("\xf0\x9f\x91\xa8");
+    VdGlyph from_family = {0}, from_man = {0};
+    loads = emoji_loads;
+    expect(glyph_cache_get_emoji(full, size, &family, &from_family), "a ZWJ sequence without an image resolves");
+    expect(emoji_loads - loads == 3 && emoji_last_length == 1,
+           "a ZWJ sequence tries itself and each shorter prefix that ends on an emoji");
+    glyph_cache_get_emoji(full, size, &man, &from_man);
+    expect(same_glyph(from_family, from_man), "a ZWJ sequence without an image draws as its first emoji");
+
+    VdEmojiSequence missing = cluster_of("\xf0\x9f\x99\x82");
+    VdGlyph none = {0};
+    expect(!glyph_cache_get_emoji(full, size, &missing, &none), "an emoji without an image does not resolve");
+    loads = emoji_loads;
+    expect(!glyph_cache_get_emoji(full, size, &missing, &none) && emoji_loads == loads,
+           "a missing image is remembered");
+
+    glyph_cache_set_emoji_loader(NULL);
+    glyph_cache_reset();
+    FILE *asset = fopen(VD_SOURCE_DIR "/assets/emoji/1f3ae.png", "rb");
+    expect(asset != NULL, "Twemoji images ship under assets/emoji, named without U+FE0F");
+    if (asset) fclose(asset);
+}
+
 static void test_pages(const VdGlyphFont *full)
 {
     glyph_cache_reset();
@@ -184,6 +309,7 @@ static void test_pages(const VdGlyphFont *full)
 int main(void)
 {
     test_utf8();
+    test_emoji_clusters();

     VdGlyphFont *full = glyph_font_load(FULL_FONT_PATH);
     VdGlyphFont *ascii = glyph_font_load(ASCII_FONT_PATH);
@@ -195,6 +321,7 @@ int main(void)
         test_hits_and_sizes(full);
         test_fallback(full, ascii);
         test_hungarian(full);
+        test_emoji(full);
         test_pages(full);
     }
